1// Member function to find the largest element in a linked list
2int find_largest(){
3    // Start from the head of the list
4    Node<T>* current = head;
5    // Initialize with the data of the first node
6    int largest = current->data;
7    // Iterate over each node in the list
8    while(current != nullptr){
9        // If current node's data is greater,
10        // update largest
11        if (current->data > largest){
12            largest = current->data;
13        }
14        // Move to the next node in the list
15        current = current->next;
16    }
17    // Return the largest element found in the list
18    return largest;
19}
